OUT.mkdir(exist_ok=True)
shutil.copytree(ROOT / 'assets', OUT / 'assets', dirs_exist_ok=True)

services = {
 'bus-verkopen': ('Bus verkopen', 'Verkoop je bus met een duidelijk verhaal.', 'Van werkbus tot personenbus: bereid je verkoop voor met de juiste gegevens en maak een zorgvuldige afweging.', [('Welke gegevens zijn belangrijk?', 'Begin met het kenteken, de kilometerstand en het bouwjaar. Vermeld ook de uitvoering, eventuele ombouw en hoe je de bus hebt gebruikt. Een bestelbus met dubbele cabine is bijvoorbeeld niet hetzelfde als een personenbus.'), ('Maak de staat inzichtelijk', 'Onderhoudsfacturen, het APK-rapport en foto’s van de binnen- en buitenkant helpen bij een beoordeling. Benoem bekende gebreken meteen. Dat voorkomt dat een eerste indicatie later op onvolledige informatie blijkt te zijn gebaseerd.'), ('Controleer de overdracht', 'Spreek af hoe de betaling en overschrijving verlopen. Geef de bus en sleutels pas mee als je de betaling hebt gecontroleerd en het vrijwaringsbewijs hebt ontvangen. Raadpleeg de RDW voor de actuele regels.')]),
 'bedrijfswagen-verkopen': ('Bedrijfswagen verkopen', 'Een volgende stap voor je bedrijfswagen.', 'Ga je overstappen op een andere bedrijfswagen of stoppen met je onderneming? Zet de verkoopgegevens en administratie eerst op een rij.', [('Btw of marge?', 'Of een voertuig een btw- of margeauto is, bepaalt mede hoe de verkoop administratief wordt verwerkt. Controleer de aankoopfactuur en bespreek jouw situatie met de boekhouder. Geef bij een prijs altijd aan of die inclusief of exclusief btw is.'), ('Inrichting en extra’s', 'Een laadklep, trekhaak, koeling, dubbele cabine of vaste bedrijfsinrichting kan relevant zijn voor een volgende eigenaar. Vermeld welke accessoires bij de verkoop blijven en controleer eventuele keuringsdocumenten.'), ('Lease en financiering', 'Als de bedrijfswagen nog wordt gefinancierd of geleased, kun je niet altijd zelfstandig verkopen. Controleer wie eigenaar is en welke toestemming of aflossing nodig is voordat je afspraken maakt.')]),
 'bestelbus-verkopen': ('Bestelbus verkopen', 'Jouw bestelbus, klaar voor de volgende rit.', 'Een bestelbus beoordelen gaat verder dan alleen het bouwjaar. Laadruimte, uitvoering en onderhoud geven samen een beter beeld.', [('Welke uitvoering heb je?', 'Vermeld lengte en hoogte, bijvoorbeeld L2H2, als je die weet. Ook laadvermogen, transmissie en brandstof zijn relevant. Raadpleeg bij twijfel de voertuiggegevens of aankoopdocumenten.'), ('Laat de laadruimte zien', 'Maak foto’s van vloer, wanden, schuifdeur en achterdeuren. Intensief gebruik hoeft geen verrassing te zijn als je slijtage duidelijk beschrijft. Geef aan of bekleding, stellingen en een tussenschot aanwezig zijn.'), ('Onderhoud telt mee', 'Een overzicht van onderhoud helpt om de technische geschiedenis te begrijpen. Vermeld recente reparaties en achterstallig werk, zonder zelf een garantie te geven die je niet kunt onderbouwen.')]),
 'bus-met-schade-verkopen': ('Bus met schade verkopen', 'Ook bij schade begint het met duidelijkheid.', 'Beschrijf wat er is gebeurd en wat nog werkt. Zo is beter te beoordelen welke mogelijkheden er voor je bus zijn.', [('Welke schade is er?', 'Maak onderscheid tussen carrosserieschade en een technisch defect. Geef aan of de bus nog start, kan rijden en veilig kan worden verplaatst. Deel foto’s van de schade en beschikbare reparatieoffertes.'), ('Veilig verplaatsen', 'Ga met een onveilige bus niet de weg op. Bespreek vooraf of transport nodig is en wie dat organiseert en betaalt. Bij een verzekeringszaak kunnen aanvullende voorwaarden gelden.'), ('Wees volledig', 'Vermeld ook bekende schade uit het verleden en eventuele problemen met airbags of chassis. Een beoordeling op afstand blijft afhankelijk van de juistheid en volledigheid van de informatie.')]),
 'bus-zonder-apk-verkopen': ('Bus zonder APK verkopen', 'Geen APK? Bereid de verkoop zorgvuldig voor.', 'Een verlopen APK vraagt aandacht bij transport en overdracht. Deel de keuringsstatus en bekende aandachtspunten vooraf.', [('Verlopen of afgekeurd?', 'Een verlopen keuring is niet hetzelfde als afkeuring. Heb je een afkeuringsrapport, deel dan de geconstateerde gebreken en een eventuele offerte. Controleer de actuele APK-status bij de RDW.'), ('Niet zomaar rijden', 'Zonder geldige APK gelden beperkingen. Raadpleeg de RDW voor de actuele uitzonderingen en voorwaarden. Organiseer waar nodig transport en maak daar vóór de overdracht afspraken over.'), ('Documenten bij de hand', 'Leg kentekencard, tenaamstellingscode en onderhoudsinformatie klaar. Deel een volledige tenaamstellingscode niet in een eerste aanvraag of met onbekenden; die is pas nodig bij de daadwerkelijke overschrijving.')]),
 'bus-met-hoge-kilometerstand': ('Bus met hoge kilometerstand', 'Meer kilometers. Meer verhaal.', 'Een hoge kilometerstand vertelt niet alles. Gebruik, onderhoud en technische staat zijn minstens zo relevant voor de beoordeling.', [('Gebruik en historie', 'Lange snelwegritten en veel korte ritten zorgen voor een andere belasting. Beschrijf het gebruik zo concreet mogelijk en vermeld hoeveel eigenaren je kent uit de beschikbare documenten.'), ('Belangrijke onderhoudspunten', 'Deel informatie over distributie, koppeling, versnellingsbak en recente grote onderhoudsbeurten. Wat relevant is, verschilt per motor en uitvoering. Facturen zijn nuttiger dan algemene uitspraken als “altijd goed onderhouden”.'), ('Kilometerstand correct vermelden', 'Gebruik de actuele tellerstand. Vermeld als een teller is vervangen of als de historie onduidelijk is. Raadpleeg waar beschikbaar de geregistreerde tellergegevens voordat je een aanvraag doet.')]),
}
