def link(path, text):
 return f'<a href="/{path}/">{escape(text)}</a>'

def logo():
 return '<a class="logo" href="/" aria-label="VerkoopJouwBus home"><span class="logo-mark" aria-hidden="true">↗</span><span>Verkoop<span>Jouw</span>Bus<span style="color:#2563eb">.</span></span></a>'

def header():
 return f'<header><div class="wrap header-row">{logo()}<button class="menu-toggle" aria-controls="navigation" aria-expanded="false">Menu</button><nav id="navigation" aria-label="Hoofdnavigatie"><details><summary>Bus verkopen</summary><div class="dropdown">{"".join(link(k,v[0]) for k,v in services.items())}</div></details>{link("hoe-werkt-het","Hoe werkt het?")}{link("contact","Contact")}</nav><a class="header-phone" href="tel:0851301900">085-130-1900</a></div></header>'

def footer():
 return '<footer class="footer"><div class="wrap"><div class="footer-lead"><div>'+logo()+'<p>VerkoopJouwBus · Persoonlijk contact over de verkoop van jouw bedrijfsbus. Helder van aanvraag tot overdracht.</p></div><div class="footer-contact"><a href="tel:0851301900">085-130-1900</a><a href="mailto:info@verkoopjouwbus.nl">info@verkoopjouwbus.nl</a><a href="https://wa.me/31851301900" target="_blank" rel="noopener noreferrer">WhatsApp ons ↗</a><p>Ma–vr 08:00–18:00</p></div></div><div class="footer-grid">'+''.join('<div><h3>'+escape(group)+'</h3>'+''.join(link(path,label) for path,label in items)+'</div>' for group,items in FOOTER_GROUPS.items())+'</div><div class="footer-bottom"><span>© VerkoopJouwBus · Alle rechten voorbehouden.</span><span>'+link('privacy','Privacy')+' '+link('voorwaarden','Voorwaarden')+'</span></div></div></footer>'

def faq_block():
 return '<div class="faq">'+''.join(f'<details><summary>{escape(q)}</summary><p>{escape(a)}</p></details>' for q,a in faqs)+'</div>'

def form():
 return '''<section class="form-section" id="aanvragen"><div class="wrap split"><div class="form-copy"><div class="eyebrow">Jouw volgende stap</div><h2>Vertel ons over<br>jouw bus.</h2><p>Vul je gegevens in om contact aan te vragen over de verkoop. Vertel ook wat we moeten weten over de staat van je bus.</p><div class="micro"><span>Geen verkoopverplichting</span><span>Jij beslist</span></div></div><form name="bus-aanvraag" method="POST" action="/bedankt/" data-netlify="true" netlify-honeypot="bedrijfspagina"><input type="hidden" name="form-name" value="bus-aanvraag"><input type="hidden" name="verkoop-situatie" value=""><p class="selected-situation" hidden></p><p class="hidden"><label>Niet invullen: <input name="bedrijfspagina" tabindex="-1" autocomplete="off"></label></p><div class="form-grid"><label>Kenteken<input class="plate" id="kenteken" name="kenteken" maxlength="12" placeholder="Bijv. AB-123-C" autocomplete="off"></label><label>Kilometerstand<input name="kilometerstand" type="number" min="0" max="3000000" placeholder="Bijv. 145000"></label><label>Merk<select name="merk"><option value="">Kies een merk</option>'''+''.join('<option>'+escape(v[0])+'</option>' for v in brands.values())+'''<option>Ander merk</option></select></label><label>Model<input name="model" placeholder="Bijv. Transit Custom"></label><label>Inrichting<input name="inrichting" placeholder="Bijv. gesloten bestelbus"></label><label>Bouwjaar<input name="bouwjaar" type="number" min="1900" max="2100"></label><label>Brandstof<select name="brandstof"><option value="">Onbekend</option><option>Diesel</option><option>Benzine</option><option>Elektrisch</option><option>Hybride</option><option>LPG</option></select></label><label>Transmissie<select name="transmissie"><option value="">Onbekend</option><option>Handgeschakeld</option><option>Automaat</option></select></label><label class="wide">APK vervaldatum<input name="apk" type="date"></label><label class="wide">Naam *<input name="naam" required autocomplete="name" maxlength="100"></label><label>E-mailadres *<input name="email" type="email" required autocomplete="email" maxlength="254"></label><label>Telefoonnummer<input name="telefoon" type="tel" autocomplete="tel" maxlength="30"></label><label class="wide">Wat moeten we weten?<textarea name="toelichting" rows="3" maxlength="2500" placeholder="Bijvoorbeeld uitvoering, onderhoud of schade. Stuur geen tenaamstellingscode mee."></textarea></label><label class="wide check"><input name="privacy-akkoord" type="checkbox" required value="ja"><span>Ik heb de <a href="/privacy/" style="text-decoration:underline">privacy-informatie</a> gelezen en wil dat er contact met mij wordt opgenomen over deze aanvraag. *</span></label><button class="btn wide" type="submit">Verstuur mijn aanvraag</button></div><p class="form-note">* Verplicht veld. Een aanvraag is geen verkoopovereenkomst. Je gegevens zijn bedoeld voor contact over deze aanvraag.</p></form></div></section>'''

def brand_grid():
 return '<div class="brand-grid">'+''.join(f'<a class="brand" href="/merken/{k}/">{escape(v[0])}<span aria-hidden="true">↗</span></a>' for k,v in brands.items())+'</div>'

pages={}

def page(path, title, description, body, faq=False, noindex=False):
 aliases={'auto-verkopen':'bus-verkopen','bedrijfsauto-verkopen':'bedrijfswagen-verkopen','auto-zonder-apk-verkopen':'bus-zonder-apk-verkopen','schadeauto-verkopen':'bus-met-schade-verkopen','auto-met-hoge-kilometerstand-verkopen':'bus-met-hoge-kilometerstand','advies/waarde/wat-bepaalt-de-waarde-van-mijn-auto':'wat-is-mijn-auto-waard'}
 canonical_path=aliases.get(path,path)
 canonical=ORIGIN+('/'+canonical_path+'/' if canonical_path else '/')
 schema=[{'@context':'https://schema.org','@type':'Organization','name':'VerkoopJouwBus','url':ORIGIN}, {'@context':'https://schema.org','@type':'WebSite','name':'VerkoopJouwBus','url':ORIGIN,'inLanguage':'nl-NL'}]
 if path:
  schema.append({'@context':'https://schema.org','@type':'BreadcrumbList','itemListElement':[{'@type':'ListItem','position':1,'name':'Home','item':ORIGIN+'/'},{'@type':'ListItem','position':2,'name':title,'item':canonical}]})
 if faq:
  schema.append({'@context':'https://schema.org','@type':'FAQPage','mainEntity':[{'@type':'Question','name':q,'acceptedAnswer':{'@type':'Answer','text':a}} for q,a in faqs]})
 html=f'''<!doctype html><html lang="nl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{escape(title)} | VerkoopJouwBus</title><meta name="description" content="{escape(description,quote=True)}"><meta name="robots" content="{'noindex,follow' if noindex else 'index,follow'}"><link rel="canonical" href="{canonical}"><meta name="theme-color" content="#133e32"><meta property="og:type" content="website"><meta property="og:locale" content="nl_NL"><meta property="og:site_name" content="VerkoopJouwBus"><meta property="og:title" content="{escape(title,quote=True)}"><meta property="og:description" content="{escape(description,quote=True)}"><meta property="og:url" content="{canonical}"><link rel="icon" href="/assets/favicon.svg" type="image/svg+xml"><link rel="preload" href="/assets/fonts/inter-latin-400-normal.woff2" as="font" type="font/woff2" crossorigin><link rel="preload" href="/assets/fonts/inter-latin-800-normal.woff2" as="font" type="font/woff2" crossorigin><link rel="stylesheet" href="/assets/style.css"><script defer src="/assets/app.js"></script><script defer src="/assets/experience.js"></script><script defer src="/assets/rdw-original.js"></script><script defer src="/assets/tools.js"></script><script type="application/ld+json">{json.dumps(schema,ensure_ascii=False)}</script></head><body><a class="skip-link" href="#inhoud">Ga naar inhoud</a>{header()}<main id="inhoud">{body}</main>{footer()}</body></html>'''
 dest=OUT/path/'index.html' if path else OUT/'index.html'
 dest.parent.mkdir(parents=True,exist_ok=True)
 html=html.replace('↗', '<svg class="icon-arrow" aria-hidden="true" viewBox="0 0 24 24"><path d="M5 19L19 5M6 5h13v13" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/></svg>')
 dest.write_text(html)
 if not noindex and path not in aliases: pages[path]=title

home='<section class="home-hero"><div class="wrap hero-sequence"><form class="hero-kenteken rdw-check"><label for="hero-plate">Voer uw kenteken in</label><div class="hero-plate-row"><span class="nl-plate" aria-hidden="true"><svg viewBox="0 0 24 24"><circle cx="12" cy="12" r="7" fill="none" stroke="#facc15" stroke-width="2" stroke-dasharray="1 3"/></svg>NL</span><input class="plate" id="hero-plate" name="rdw-kenteken" placeholder="VUL UW KENTEKEN IN" maxlength="10" required autocomplete="off" aria-label="Kenteken"></div><button class="btn" type="submit">Bekijk mijn bus</button><a class="manual-link" href="#aanvragen">Doorgaan zonder kenteken</a><div class="rdw-result" role="status" aria-live="polite"></div></form><div class="hero-copy"><div class="eyebrow">Uw volgende hoofdstuk begint hier</div><h1>Uw bus. Klaar voor de <em>volgende stap.</em></h1><p>Van trouwe werkbus naar een nieuwe bestemming. Ontdek de mogelijkheden voor uw bus, met persoonlijk contact en heldere afspraken.</p><p class="hero-reassurance"><span class="checkmark" aria-hidden="true">✓</span> U beslist of u verkoopt. Een aanvraag is vrijblijvend.</p></div><div class="hero-photo"><div class="photo-caption"><span>Ruimte voor iets nieuws.</span><strong>De volgende rit is aan u.</strong></div><img src="/assets/bus-hero.webp" width="1536" height="1024" alt="Witte bedrijfsbus bij een modern bedrijfspand" fetchpriority="high"></div></div></section><div class="trust-bar"><div class="wrap"><span>✓ Vrijblijvend aanmelden</span><span>✓ Persoonlijk contact</span><span>✓ Bestelbussen en bedrijfswagens</span></div></div>SITUATION_COMPONENT<section id="hoe-werkt-het" class="home-section"><div class="wrap"><div class="center-heading"><span class="eyebrow">Eenvoudig van start</span><h2>Van eerste klik<br>naar een helder plan.</h2><p>Drie overzichtelijke stappen. U houdt het stuur in handen.</p></div><div class="process-grid"><div class="process-item"><span class="step-number">1</span><div class="process-symbol plate-symbol">NL <strong>AB-123-C</strong></div><h3>Vraag een vrijblijvend bod aan</h3><p>Vul uw kenteken in en deel de gegevens en staat van uw bedrijfsbus.</p></div><div class="process-item"><span class="step-number">2</span><div class="process-symbol">↗</div><h3>Bespreek de mogelijkheden</h3><p>Bekijk een concreet aanbod en controleer de prijs en bijbehorende afspraken.</p></div><div class="process-item"><span class="step-number">3</span><div class="process-symbol">✓</div><h3>Regel de overdracht</h3><p>Spreek inspectie en transport af. Controleer betaling en vrijwaring.</p></div></div></div></section><section class="home-section why-section" id="voordelen"><div class="wrap why-grid"><div><span class="eyebrow">Helder en persoonlijk</span><h2>Een werkbus is meer<br>dan vier wielen.</h2><p class="lead">Vroege starts, volle laadruimtes, duizenden kilometers. Uw bus heeft een verhaal. Daar nemen we de tijd voor.</p><div class="benefit-list"><div><span>✓</span><div><h3>U houdt de regie</h3><p>Een aanvraag is vrijblijvend. U beslist pas na een concreet aanbod.</p></div></div><div><span>✓</span><div><h3>Direct persoonlijk contact</h3><p>Bel, mail of stuur een WhatsApp-bericht over uw bedrijfsbus.</p></div></div><div><span>✓</span><div><h3>Ook bij schade of veel kilometers</h3><p>Beschrijf de staat van uw bus zodat de mogelijkheden kunnen worden beoordeeld.</p></div></div><div><span>✓</span><div><h3>Duidelijke afspraken</h3><p>Bespreek inspectie, transport, betaling en overschrijving vooraf.</p></div></div></div></div><div class="why-photo"><img src="/assets/bus-hero.webp" width="1536" height="1024" alt="Witte bestelbus klaar voor een volgende eigenaar" loading="lazy"><div class="why-photo-caption">Een nieuwe bestemming.<br><strong>Goed voorbereid.</strong></div></div></div></section><section class="home-section"><div class="wrap"><div class="center-heading"><span class="eyebrow">Een goed beeld van uw bus</span><h2>Wat is uw bedrijfsbus waard?</h2><p>Een indicatie is geen definitief bod. Deze vier onderdelen helpen bij een beoordeling.</p></div><div class="value-grid"><article><span>01</span><h3>Bouwjaar en kilometerstand</h3><p>Leeftijd, gebruik en de actuele tellerstand geven samen een eerste beeld.</p></article><article><span>02</span><h3>Onderhoud en APK</h3><p>Facturen en keuringsinformatie maken de historie inzichtelijk.</p></article><article><span>03</span><h3>Schade en gebreken</h3><p>Benoem bekende problemen en deel foto\'s bij verdere beoordeling.</p></article><article><span>04</span><h3>Uitvoering en vraag</h3><p>Laadruimte, brandstof en inrichting bepalen voor wie uw bus bruikbaar is.</p></article></div><div class="inline-links"><a href="/wat-is-mijn-auto-waard/">Wat is mijn bus waard? ↗</a><a href="/afschrijving-auto/">Afschrijving berekenen ↗</a><a href="/advies/waarde/wat-bepaalt-de-waarde-van-mijn-auto/">Wat bepaalt de waarde? ↗</a></div></div></section><section class="home-section brands-section"><div class="wrap"><div class="center-heading"><h2>Van compacte krachtpatser<br>tot grote kilometermaker.</h2><p>Van compacte bestelwagen tot ruime werkbus.</p></div>BRAND_GRID</div></section><section class="home-section"><div class="wrap faq-wrap"><div class="center-heading"><span class="eyebrow">Goed om te weten</span><h2>Veelgestelde vragen</h2></div>FAQ_BLOCK</div></section><section class="home-section further-section"><div class="wrap"><div class="center-heading"><span class="eyebrow">Verder lezen</span><h2>Meer over uw bus verkopen</h2><p>Praktische uitleg voor uw situatie, merk of verkooproute.</p></div>ROUTE_CARDS</div></section><section class="final-cta"><div class="wrap"><h2>Een nieuwe bestemming<br>begint bij uw kenteken.</h2><p>Begin met uw kenteken, of vul uw gegevens handmatig in.</p><a class="btn" href="#aanvragen">Vraag een vrijblijvend bod aan</a><div class="micro"><span>Vrijblijvend</span><span>Persoonlijk contact</span><span>U beslist</span></div></div></section>FORM_BLOCK'
home=home.replace('SITUATION_COMPONENT',(ROOT/'components/situation.html').read_text())
