def intro(title, heading, description):
 return f'<div class="wrap"><div class="breadcrumb"><a href="/">Home</a> / {escape(title)}</div><div class="page-intro"><div class="eyebrow">Uw volgende hoofdstuk begint hier</div><h1>{escape(heading)}</h1><p>{escape(description)}</p><a class="btn" href="/#aanvragen">Meld je bus aan</a></div></div>'

for slug,(title,heading,description,sections) in services.items():
 body=intro(title,heading,description)+'<div class="wrap"><section class="article">'+''.join(f'<h2>{escape(h)}</h2><p>{escape(p)}</p>' for h,p in sections)+f'<div class="cta"><h2>Maak de volgende stap concreet.</h2><p>Deel de basisgegevens van je bus. Een aanvraag verplicht je nergens toe.</p><a class="btn" href="/#aanvragen">Vraag contact aan</a></div><h2>Lees ook</h2><ul>'+''.join(f'<li>{link(k,v[0])}</li>' for k,v in services.items() if k!=slug)+'</ul></section></div>'
 page(slug,title,description,body)
for slug,(name,models,advice) in brands.items():
 description=f'Je {name} bus verkopen? Lees welke gegevens belangrijk zijn bij {models} en meld je bedrijfswagen aan bij VerkoopJouwBus.'
 body=intro(name+' bus verkopen',f'Je {name} bus. Een nieuwe bestemming.',description)+f'<div class="wrap"><section class="article"><h2>{escape(models)}</h2><p>{escape(advice)}</p><h2>Zo bereid je een aanvraag voor</h2><ul><li>Controleer kenteken, bouwjaar en actuele kilometerstand.</li><li>Beschrijf uitvoering, onderhoud en bekende gebreken.</li><li>Houd foto’s en onderhoudsfacturen klaar voor verdere beoordeling.</li><li>Vermeld of je particulier of zakelijk verkoopt en of er financiering loopt.</li></ul><p>Merk en model alleen bepalen de waarde niet. De staat, historie en specifieke uitvoering blijven belangrijk.</p><div class="cta"><h2>Klaar voor de volgende stap?</h2><a class="btn" href="/#aanvragen">Meld je {escape(name)} aan</a></div><h2>Meer informatie</h2>{link("bedrijfswagen-verkopen","Lees over je bedrijfswagen verkopen →")}</section></div>'
